/* Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT */
:where([data-moru-registry]) .ui-alert-dialog {
  box-sizing: border-box;
  min-width: 0;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-body-size, 14px);
  font-weight: var(--ui-type-body-weight, 400);
  line-height: var(--ui-type-body-line-height, 1.6);
  letter-spacing: var(--ui-type-body-letter-spacing, 0em);
  color: var(--ui-text, #171717);
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: calc(var(--ui-radius, 6px) + 4px);
  background: var(--ui-surface, #fff);
  box-shadow: var(--ui-shadow, 0 8px 28px #00000016);
  overflow-wrap: anywhere;
}

:where([data-moru-registry]) .ui-alert-dialog {
  position: fixed;
  z-index: 71;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  width: min(440px, calc(100vw - 32px));
  max-height: calc(100dvh - 32px);
  padding: var(--ui-card-padding, 24px);
  overflow-y: auto;
  overscroll-behavior: contain;
  transform: translate(-50%, -50%);
  transition:
    opacity var(--ui-duration, 160ms),
    scale var(--ui-duration, 160ms);
}

:where([data-moru-registry]) .ui-alert-dialog[data-starting-style],
:where([data-moru-registry]) .ui-alert-dialog[data-ending-style] {
  opacity: 0;
  scale: 0.97;
}

:where([data-moru-registry]) .ui-alert-dialog:focus-visible {
  outline: 2px solid var(--ui-focus-ring, #181818);
  outline-offset: -3px;
}

:where([data-moru-registry]) .ui-alert-dialog-mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--ui-control-height-md, 40px);
  height: var(--ui-control-height-md, 40px);
  margin-block-end: var(--ui-form-gap, 24px);
  border: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
  border-radius: var(--ui-radius, 6px);
  color: var(--ui-primary-surface-text, #181818);
  background: var(--ui-control-hover-bg, #f3f3f1);
  border-color: transparent;
}

:where([data-moru-registry]) .ui-alert-dialog-mark[data-destructive] {
  color: var(--ui-danger-text, #be4545);
  border-color: var(--ui-danger-border, #edc8c8);
  background: var(--ui-danger-soft, #faf0f0);
}

:where([data-moru-registry]) .ui-alert-dialog-actions {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: var(--ui-control-gap, 8px);
  margin-block-start: var(--ui-form-gap, 24px);
  padding-block-start: var(--ui-form-gap, 24px);
  border-block-start: var(--ui-border-width, 1px) solid var(--ui-border, #e8e8e4);
}

:where([data-moru-registry]) .ui-alert-dialog-actions > .ui-button {
  max-width: 100%;
  height: auto;
  white-space: normal;
  overflow-wrap: anywhere;
}

@media (max-width: 540px) {
  :where([data-moru-registry]) .ui-alert-dialog-actions {
    flex-direction: column-reverse;
  }
  :where([data-moru-registry]) .ui-alert-dialog-actions > button {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  :where([data-moru-registry]) .ui-alert-dialog {
    transition: none;
  }
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentPropsWithoutRef,
  type ReactElement,
} from 'react'
import { AlertDialog as BaseAlertDialog } from '@base-ui/react/alert-dialog'
import { CircleAlert } from 'lucide-react'
import { Button } from './button'
import { useThemePortalContainer } from './theme-scope'
import { OverlayPortal } from './overlay-portal'
import './overlay-shared.css'
import './alert-dialog.css'

export interface AlertDialogProps {
  trigger?: ReactElement
  title: string
  description?: string
  confirmLabel?: string
  cancelLabel?: string
  onConfirm: () => void | Promise<void>
  open?: boolean
  onOpenChange?: (open: boolean) => void
  destructive?: boolean
  loading?: boolean
  /** Focus a stable destination after confirmation removes the original trigger. */
  finalFocus?: ComponentPropsWithoutRef<typeof BaseAlertDialog.Popup>['finalFocus']
}

/** Explicit confirmation with safe initial focus and recoverable async errors. */
export function AlertDialog({
  trigger,
  title,
  description,
  confirmLabel: confirmLabelProp,
  cancelLabel: cancelLabelProp,
  onConfirm,
  open,
  onOpenChange,
  destructive = false,
  loading = false,
  finalFocus,
}: AlertDialogProps) {
  const { t } = useI18n()
  const confirmLabel = confirmLabelProp ?? t('확인')
  const cancelLabel = cancelLabelProp ?? t('취소')

  const portalContainer = useThemePortalContainer()
  const [internalOpen, setInternalOpen] = useState(false)
  const [confirming, setConfirming] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const cancelRef = useRef<HTMLButtonElement>(null)
  const popupRef = useRef<HTMLDivElement>(null)
  const pendingRef = useRef(false)
  const mountedRef = useRef(true)
  const sessionRef = useRef(0)
  const isOpen = open ?? internalOpen
  const busy = loading || confirming

  useLayoutEffect(() => {
    const popup = popupRef.current
    if (!isOpen || !busy || !popup) return
    // Disabling the focused action can move browser focus to body. Keep it in
    // the confirmation while all actions are unavailable, including on error.
    const active = popup.ownerDocument.activeElement
    if (active === popup.ownerDocument.body || (active && popup.contains(active))) {
      popup.focus({ preventScroll: true })
    }
  }, [isOpen, busy])

  useEffect(() => {
    mountedRef.current = true
    return () => {
      mountedRef.current = false
    }
  }, [])

  useEffect(() => {
    if (!isOpen) {
      sessionRef.current += 1
      pendingRef.current = false
      setConfirming(false)
      setError(null)
    }
  }, [isOpen])

  function changeOpen(nextOpen: boolean) {
    if (!nextOpen && (pendingRef.current || loading)) return
    if (open === undefined) setInternalOpen(nextOpen)
    if (nextOpen) setError(null)
    onOpenChange?.(nextOpen)
  }

  async function confirm() {
    if (pendingRef.current || loading) return
    pendingRef.current = true
    setConfirming(true)
    setError(null)
    const session = sessionRef.current
    try {
      await onConfirm()
      if (!mountedRef.current || session !== sessionRef.current) return
      pendingRef.current = false
      setConfirming(false)
      changeOpen(false)
    } catch (reason) {
      if (!mountedRef.current || session !== sessionRef.current) return
      pendingRef.current = false
      setConfirming(false)
      setError(
        reason instanceof Error && reason.message.trim()
          ? reason.message
          : t('처리하지 못했습니다. 다시 시도해 주세요.'),
      )
    }
  }

  return (
    <BaseAlertDialog.Root
      open={isOpen}
      onOpenChange={(nextOpen, details) => {
        if (!nextOpen && (pendingRef.current || loading)) {
          details.cancel()
          return
        }
        changeOpen(nextOpen)
      }}
    >
      {trigger && <BaseAlertDialog.Trigger render={trigger} />}
      <OverlayPortal portal={BaseAlertDialog.Portal} kind="modal" container={portalContainer}>
        <BaseAlertDialog.Backdrop className="ui-overlay-backdrop" />
        <BaseAlertDialog.Popup
          ref={popupRef}
          className="ui-alert-dialog"
          initialFocus={() =>
            cancelRef.current && !cancelRef.current.disabled ? cancelRef.current : popupRef.current
          }
          finalFocus={finalFocus}
          aria-busy={busy || undefined}
        >
          <div className="ui-alert-dialog-mark" data-destructive={destructive || undefined}>
            <CircleAlert size={20} aria-hidden="true" />
          </div>
          <BaseAlertDialog.Title className="ui-overlay-title">{title}</BaseAlertDialog.Title>
          {description && (
            <BaseAlertDialog.Description className="ui-overlay-description">
              {description}
            </BaseAlertDialog.Description>
          )}
          {error && (
            <p className="ui-confirmation-error" role="alert">
              {error}
            </p>
          )}
          <div className="ui-alert-dialog-actions">
            <BaseAlertDialog.Close
              render={<Button ref={cancelRef} variant="secondary" disabled={busy} />}
            >
              {cancelLabel}
            </BaseAlertDialog.Close>
            <Button
              variant={destructive ? 'danger' : 'primary'}
              loading={busy}
              onClick={() => {
                void confirm()
              }}
            >
              {confirmLabel}
            </Button>
          </div>
        </BaseAlertDialog.Popup>
      </OverlayPortal>
    </BaseAlertDialog.Root>
  )
}
